let palette = ['#f70640', '#193680', '#232323'];
let ctx;
let centerX, centerY;
let rects = [];
let shapeCounter = 0;
let minShapeSize;
let layoutCycleFrames = 95;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	minShapeSize = width * 0.08;
	initializeLayout();
}

function draw() {
	background('#eef0ff');
	for (let r of rects) {
		r.run();
	}

	if (frameCount % layoutCycleFrames == 0) {
		initializeLayout()
	}
}

function initializeLayout() {
	rects = [];
	let randomW = random(0.2, 0.75) * width;
	let randomH = random(0.2, 0.75) * height;
	addObj_divideRect(centerX, centerY, randomW, randomH);
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

function addShapes_Grid(x, y, w, n) {
	let cellW = w / n;
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			let cellX = i * cellW + (cellW / 2) - (w / 2) + x;
			let cellY = j * cellW + (cellW / 2) - (w / 2) + y;
			rects.push(new RectMotion(cellX, cellY, cellW, cellW / 2, shapeCounter * 2));
			shapeCounter++;
		}
	}
}

function addObj_divideRect(x, y, w, h) {
	if (min(w, h) > minShapeSize) {
		let w1 = w * random(0.3, 0.7);
		let h1 = h * random(0.3, 0.7);
		let w2 = w - w1;
		let h2 = h - h1;
		let crossroad = w >= h;
		if (crossroad) {
			addObj_divideRect(x - (w / 2) + (w1 / 2), y, w1, h);
			addObj_divideRect(x + (w / 2) - (w2 / 2), y, w2, h);
		} else {
			addObj_divideRect(x, y - (h / 2) + (h1 / 2), w, h1);
			addObj_divideRect(x, y + (h / 2) - (h2 / 2), w, h2);
		}

	} else {
		rects.push(new RectMotion(x, y, w, h, int(random(27))));
	}
}

/*------------------------------------------------------------------------------------------*/

class RectMotion {
	constructor(x, y, w, h, t) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.motionType = int(random(4));
		this.timer = -t;
		this.phase1 = 39;
		this.phase2 = this.phase1 + 39;

		this.clr = random(palette);

		this.maxCorner = min(w, h) / 2;
		this.corner = this.maxCorner;
		this.shapeScale = 0;

		this.subRectW = 0;
		this.subRectH = 0;
		this.subRectOffsetX = this.w / 2;
		this.subRectOffsetY = this.h / 2;

		this.stripWidth = 0;
		this.holeWidth = this.w / 2;
		this.holeHeight = this.h / 2;
	}

	display() {
		push();
		translate(this.x, this.y);
		noStroke();
		fill(this.clr);
		ctx.shadowColor = '#000000';

		if (this.motionType === 0) {
			scale(this.shapeScale);
			rect(0, 0, this.w, this.h, this.corner);
		} else if (this.motionType === 1) {
			rect(this.subRectOffsetX, this.subRectOffsetY, this.subRectW, this.subRectH);
			rect(-this.subRectOffsetX, this.subRectOffsetY, this.subRectW, this.subRectH);
			rect(this.subRectOffsetX, -this.subRectOffsetY, this.subRectW, this.subRectH);
			rect(-this.subRectOffsetX, -this.subRectOffsetY, this.subRectW, this.subRectH);
		} else if (this.motionType === 2) {
			beginShape();
			vertex(-this.w / 2, -this.h / 2);
			vertex(-(this.w / 2) + this.stripWidth, -this.h / 2);
			vertex(-(this.w / 2) + this.stripWidth, this.h / 2);
			vertex(-this.w / 2, this.h / 2);
			endShape(CLOSE);
		} else if (this.motionType === 3) {
			beginShape();
			vertex(-this.w / 2, -this.h / 2);
			vertex(this.w / 2, -this.h / 2);
			vertex(this.w / 2, this.h / 2);
			vertex(-this.w / 2, this.h / 2);

			beginContour();
			vertex(-this.holeWidth, -this.holeHeight);
			vertex(-this.holeWidth, this.holeHeight);
			vertex(this.holeWidth, this.holeHeight);
			vertex(this.holeWidth, -this.holeHeight);
			endContour();
			endShape(CLOSE);
		}
		pop();
	}

	update() {
		this.timer++

		if (0 < this.timer && this.timer < this.phase1) {
			let n = norm(this.timer, 0, this.phase1 - 1);
			this.corner = lerp(this.maxCorner, 0, easeInOutQuart(n));
			this.shapeScale = lerp(0, 1, easeInOutQuart(n));
			this.subRectOffsetX = this.w / lerp(2, 4, easeInOutQuart(n));
			this.subRectOffsetY = this.h / lerp(2, 4, easeInOutQuart(n));
			this.subRectW = lerp(0, this.w / 2, easeInOutQuart(n));
			this.subRectH = lerp(0, this.h / 2, easeInOutQuart(n));
			this.stripWidth = lerp(0, this.w, easeInOutQuart(n));
			this.holeWidth = lerp(this.w / 2, 0, easeInOutQuart(n));
			this.holeHeight = lerp(this.h / 2, 0, easeInOutQuart(n));
		} else if (this.phase1 < this.timer && this.timer < this.phase2) {
			let n = norm(this.timer, this.phase1, this.phase2 - 1);
			this.corner = lerp(0, this.maxCorner, easeInOutQuart(n));
			this.shapeScale = lerp(1, 0, easeInOutQuart(n));
			this.subRectOffsetX = this.w / lerp(4, 2, easeInOutQuart(n));
			this.subRectOffsetY = this.h / lerp(4, 2, easeInOutQuart(n));
			this.subRectW = lerp(this.w / 2, 0, easeInOutQuart(n));
			this.subRectH = lerp(this.h / 2, 0, easeInOutQuart(n));
			this.stripWidth = lerp(this.w, 0, easeInOutQuart(n));
			this.holeWidth = lerp(0, this.w / 2, easeInOutQuart(n));
			this.holeHeight = lerp(0, this.h / 2, easeInOutQuart(n));
		}
	}

	run() {
		this.display();
		this.update();
	}
}

